#!/usr/bin/env python3
"""Build a libxml2 xml-fuzz input from a main doc + named sub-entities."""
import struct, sys

def write_string(s):
    # backslash-newline terminates; backslash escaped as double backslash
    out = bytearray()
    for b in s:
        if isinstance(b, int):
            c = b
        else:
            c = ord(b)
        if c == 0x5c:  # backslash
            out.append(0x5c)
            out.append(0x5c)
        else:
            out.append(c)
    out.append(0x5c)  # terminator backslash
    out.append(0x0a)  # newline
    return bytes(out)

def build(opts, main_url, main_doc, entities=None):
    data = struct.pack("<i", opts)
    data += write_string(main_url.encode())
    data += write_string(main_doc.encode())
    if entities:
        for url, content in entities:
            data += write_string(url.encode())
            data += write_string(content.encode())
    return data

if __name__ == "__main__":
    # quick demo
    XML_PARSE_XINCLUDE = 1 << 10
    opts = XML_PARSE_XINCLUDE
    main = '<a xmlns:xi="http://www.w3.org/2001/XInclude"><xi:include href="b.xml"/></a>'
    b = '<b>hi</b>'
    data = build(opts, "doc.xml", main, [("b.xml", b)])
    sys.stdout.buffer.write(data)
